   486  /**
   487   * xmlXIncludeAddNode:
   488   * @ctxt:  the XInclude context
   489   * @cur:  the new node
   490   *
   491   * Add a new node to process to an XInclude context
   492   */
   493  static int
   494  xmlXIncludeAddNode(xmlXIncludeCtxtPtr ctxt, xmlNodePtr cur) {
   495      xmlXIncludeRefPtr ref;
   496      xmlURIPtr uri;
   497      xmlChar *URL;
   498      xmlChar *fragment = NULL;
   499      xmlChar *href;
   500      xmlChar *parse;
   501      xmlChar *base;
   502      xmlChar *URI;
   503      int xml = 1, i; /* default Issue 64 */
   504      int local = 0;
   505
   506
   507      if (ctxt == NULL)
   508          return(-1);
   509      if (cur == NULL)
   510          return(-1);
   511
   512  #ifdef DEBUG_XINCLUDE
   513      xmlGenericError(xmlGenericErrorContext, "Add node\n");
   514  #endif
   515      /*
   516       * read the attributes
   517       */
   518      href = xmlXIncludeGetProp(ctxt, cur, XINCLUDE_HREF);
   519      if (href == NULL) {
   520          href = xmlStrdup(BAD_CAST ""); /* @@@@ href is now optional */
   521          if (href == NULL)
   522              return(-1);
   523      }
   524      if ((href[0] == '#') || (href[0] == 0))
   525          local = 1;
   526      parse = xmlXIncludeGetProp(ctxt, cur, XINCLUDE_PARSE);
   527      if (parse != NULL) {
   528          if (xmlStrEqual(parse, XINCLUDE_PARSE_XML))
   529              xml = 1;
   530          else if (xmlStrEqual(parse, XINCLUDE_PARSE_TEXT))
   531              xml = 0;
   532          else {
   533              xmlXIncludeErr(ctxt, cur, XML_XINCLUDE_PARSE_VALUE,
   534                             "invalid value %s for 'parse'\n", parse);
   535              if (href != NULL)
   536                  xmlFree(href);
   537              if (parse != NULL)
   538                  xmlFree(parse);
   539              return(-1);
   540          }
   541      }
   542
   543      /*
   544       * compute the URI
   545       */
   546      base = xmlNodeGetBase(ctxt->doc, cur);
   547      if (base == NULL) {
   548          URI = xmlBuildURI(href, ctxt->doc->URL);
   549      } else {
   550          URI = xmlBuildURI(href, base);
   551      }
   552      if (URI == NULL) {
   553          xmlChar *escbase;
   554          xmlChar *eschref;
   555          /*
   556           * Some escaping may be needed
   557           */
   558          escbase = xmlURIEscape(base);
   559          eschref = xmlURIEscape(href);
   560          URI = xmlBuildURI(eschref, escbase);
   561          if (escbase != NULL)
   562              xmlFree(escbase);
   563          if (eschref != NULL)
   564              xmlFree(eschref);
   565      }
   566      if (parse != NULL)
   567          xmlFree(parse);
   568      if (href != NULL)
   569          xmlFree(href);
   570      if (base != NULL)
   571          xmlFree(base);
   572      if (URI == NULL) {
   573          xmlXIncludeErr(ctxt, cur, XML_XINCLUDE_HREF_URI,
   574                         "failed build URL\n", NULL);
   575          return(-1);
   576      }
   577      fragment = xmlXIncludeGetProp(ctxt, cur, XINCLUDE_PARSE_XPOINTER);
   578
   579      /*
   580       * Check the URL and remove any fragment identifier
   581       */
   582      uri = xmlParseURI((const char *)URI);
   583      if (uri == NULL) {
   584          xmlXIncludeErr(ctxt, cur, XML_XINCLUDE_HREF_URI,
   585                         "invalid value URI %s\n", URI);
   586          if (fragment != NULL)
   587              xmlFree(fragment);
   588          xmlFree(URI);
   589          return(-1);
   590      }
   591
   592      if (uri->fragment != NULL) {
   593          if (ctxt->legacy != 0) {
   594              if (fragment == NULL) {
   595                  fragment = (xmlChar *) uri->fragment;
   596              } else {
   597                  xmlFree(uri->fragment);
   598              }
   599          } else {
   600              xmlXIncludeErr(ctxt, cur, XML_XINCLUDE_FRAGMENT_ID,
   601         "Invalid fragment identifier in URI %s use the xpointer attribute\n",
   602                             URI);
   603              if (fragment != NULL)
   604                  xmlFree(fragment);
   605              xmlFreeURI(uri);
   606              xmlFree(URI);
   607              return(-1);
   608          }
   609          uri->fragment = NULL;
   610      }
   611      URL = xmlSaveUri(uri);
   612      xmlFreeURI(uri);
   613      xmlFree(URI);
   614      if (URL == NULL) {
   615          xmlXIncludeErr(ctxt, cur, XML_XINCLUDE_HREF_URI,
   616                         "invalid value URI %s\n", URI);
   617          if (fragment != NULL)
   618              xmlFree(fragment);
   619          return(-1);
   620      }
   621
   622      /*
   623       * If local and xml then we need a fragment
   624       */
   625      if ((local == 1) && (xml == 1) &&
   626          ((fragment == NULL) || (fragment[0] == 0))) {
   627          xmlXIncludeErr(ctxt, cur, XML_XINCLUDE_RECURSION,
   628                         "detected a local recursion with no xpointer in %s\n",
   629                         URL);
   630          xmlFree(URL);
   631          xmlFree(fragment);
   632          return(-1);
   633      }
   634
   635      /*
   636       * Check the URL against the stack for recursions
   637       */
   638      if ((!local) && (xml == 1)) {
   639          for (i = 0;i < ctxt->urlNr;i++) {
   640              if (xmlStrEqual(URL, ctxt->urlTab[i])) {
   641                  xmlXIncludeErr(ctxt, cur, XML_XINCLUDE_RECURSION,
   642                                 "detected a recursion in %s\n", URL);
   643                  xmlFree(URL);
   644                  xmlFree(fragment);
   645                  return(-1);
   646              }
   647          }
   648      }
   649
   650      ref = xmlXIncludeNewRef(ctxt, URL, cur);
